"""Plain-language descriptions for the documented augmentation catalog."""
DESCRIPTIONS = {
    'AdditiveNoise': 'Add independent noise to each voxel. Supports uniform, Gaussian, Laplace and centered beta distributions; this example uses Laplace noise.',
    'Affine': 'Rotate, translate and scale the volume, applying the same geometry to images and labels.',
    'BiasField': 'Multiply intensities by a smooth 3D gain field generated from a coarse Gaussian random lattice.',
    'BlankRectangle': 'Fill randomly placed cuboids with a chosen value, simulating missing regions.',
    'BrightnessAdd': 'Add a constant offset to every voxel in the selected image channels.',
    'BrightnessGradient': 'Add a localized Gaussian brightness field. This example fixes its center at the middle of the volume; `loc=(0, 1)` samples a random position. The field is mean-centered by default.',
    'BrightnessMultiply': 'Multiply every voxel in the selected image channels by a brightness factor.',
    'ChannelMisalignment': 'Independently shift, rotate and scale selected image channels to simulate registration errors. This example moves the second of two identical CT channels.',
    'CLAHE': 'Equalize local histograms in 3D tiles, limit their contrast, and interpolate between neighboring tiles to avoid seams.',
    'ClipOutliers': 'Clip intensities at selected percentiles. This example then restores the original standard deviation.',
    'Contrast': 'Scale intensity differences from the channel mean. The default range-preservation option clips results to the original range.',
    'CropPad': 'Crop or pad all aligned targets to a requested ZYX shape. This example takes a centered 112³ crop from the 128³ input.',
    'Defocus': 'Average intensities within a spherical 3D neighborhood to simulate out-of-focus acquisition.',
    'Elastic': 'Warp the volume with a smooth random 3D B-spline displacement field, keeping images and labels aligned. The previews use interior slices so boundary padding does not dominate the view.',
    'Equalize': 'Equalize the histogram across the entire volume while retaining the channel intensity range.',
    'FDA': 'Blend low-frequency amplitudes from a reference volume into the 3D Fourier spectrum while preserving the source phase.',
    'Flip': 'Mirror the volume along selected axes. This example always flips X.',
    'ForegroundCrop': 'Choose a random crop containing a sampled foreground voxel. All aligned targets follow the crop; empty masks fall back to random cropping.',
    'ForegroundDropout': 'Place cuboids around sampled foreground voxels and erase only foreground inside those cuboids.',
    'Gamma': 'Apply a power-law intensity curve over the channel range, changing the relative brightness of dark and light structures.',
    'GaussianBlur': 'Smooth the volume with a separable 3D Gaussian filter.',
    'GaussianNoise': 'Add independent zero-mean Gaussian noise with the specified standard deviation.',
    'GibbsRinging': 'Truncate high frequencies in the 3D Fourier spectrum, creating ringing around sharp boundaries.',
    'GridDropout': 'Erase a periodic grid of cuboid holes with a randomly sampled offset.',
    'HistogramMatching': 'Match the volume intensity histogram to a reference volume, with optional blending.',
    'Illumination': 'Apply a smooth multiplicative illumination field. Supports directional ramps, corner falloff and Gaussian illumination; this example uses a diagonal ramp.',
    'Invert': 'Reflect intensities around the channel mean, reversing bright and dark structures.',
    'LocalContrast': 'Change contrast around a Gaussian-weighted local mean inside a smooth region.',
    'LocalGamma': 'Blend a gamma-adjusted image into a localized Gaussian region.',
    'LocalSmoothing': 'Blend Gaussian smoothing into a localized region, leaving distant voxels largely unchanged.',
    'LowResolution': 'Downsample and upsample the image to simulate reduced spatial resolution.',
    'MedianFilter': 'Replace each voxel with the median of its 3D neighborhood, suppressing isolated noise while retaining edges.',
    'Morphology': 'Apply a morphological operation to labels. This example closes small gaps using dilation followed by erosion.',
    'MotionBlur': 'Average samples along a 3D line to simulate motion during acquisition.',
    'MultiplicativeNoise': 'Multiply each voxel by an independently sampled uniform random gain.',
    'Normalize': 'Normalize intensities per channel. This example uses z-score normalization of nonzero voxels, keeping zeros unchanged; its display window includes negative values.',
    'ObjectDropout': 'Randomly remove whole connected foreground objects, clearing their image voxels and labels by default.',
    'OrientedBlur': 'Smooth along a specified 3D direction and two perpendicular directions with separate blur widths. This example is aligned with Z.',
    'PixelDistributionAdaptation': 'Transfer reference intensity statistics. The standard mode shown here blends the reference mean and standard deviation; minmax mode transfers the range.',
    'PlasmaBrightnessContrast': 'Use a smooth multiscale 3D random field to vary brightness and contrast throughout the volume.',
    'PlasmaShadow': 'Darken the volume with a smooth multiscale 3D random shadow field.',
    'RandomBinaryOperator': 'Apply a selected binary morphological operation to image channels. This example dilates a thresholded foreground volume.',
    'RandomToneCurve': 'Apply a random monotone nonlinear intensity curve while preserving the channel range endpoints.',
    'RemoveComponents': 'Randomly remove connected foreground components below a size threshold. This example modifies the label mask.',
    'RicianNoise': 'Combine the image with two independent Gaussian noise fields to simulate magnitude-image Rician noise.',
    'RingingOvershoot': 'Apply a separable windowed-sinc filter in 3D, retaining edge overshoot and ringing.',
    'Rotate90': 'Rotate aligned targets by multiples of 90 degrees. This example rotates the YX plane by one quarter turn.',
    'SaltAndPepper': 'Replace selected voxels with the channel minimum or maximum, producing dark and bright impulse noise.',
    'Sharpen': 'Enhance local edges with a discrete Laplacian sharpening filter. This example keeps overshoots instead of clipping them.',
    'SheetCompression': 'Use the CT intensity profile to compress sheet-like structures along a selected axis while transforming aligned targets together.',
    'ShotNoise': 'Sample Poisson photon counts from nonnegative intensities and rescale them, producing signal-dependent shot noise.',
    'SliceIllumination': 'Reduce brightness across selected slices and wider bands to simulate slice-dependent acquisition defects.',
    'Smear': 'Blend shifted copies of preceding slices into each slice to simulate directional smearing.',
    'StripeMasking': 'Erase periodic slabs along selected axes with random offsets; overlapping slabs form a stripe pattern through the volume.',
    'ThickSlice': 'Downsample and upsample along selected axes to simulate thicker acquisition slices. Labels follow the same slice mapping.',
    'Transpose': 'Permute spatial axes for all aligned targets. This example exchanges Y and X.',
    'UnsharpMask': 'Add a scaled difference between the image and a Gaussian-smoothed copy to enhance fine structure.',
    'Vignetting': 'Attenuate intensities with a radial falloff in all three dimensions, darkening voxels farther from the center.',
    'ZoomBlur': 'Average multiple 3D zoom states around a center point to create radial blur.',
    'StripGeometry': 'Warp a 2D strip with rotation and a smooth lateral offset. This companion example uses the central Z slice of the CT crop.',
    'SurfacePerturb': 'Add localized smooth displacements to a 2D coordinate surface. This companion uses a synthetic surface with CT-derived height; the last panel shows displacement magnitude.',
}
